def test_no_suggestion_without_rule(ledger, reorder):
    stock(ledger, NUTS, SHELF_A, 1)

    result = reorder.check(NUTS, NOW)

    assert result is None
    assert reorder.suggestions == []
    assert reorder.rules == {}

