def test_rule_point_cannot_be_negative(reorder):
    with pytest.raises(ValueError):
        reorder.add_rule(BOLTS, point=-1, qty=50, supplier="FAST")

    with pytest.raises(ValueError):
        reorder.add_rule(BOLTS, point=10, qty=0, supplier="FAST")

    assert reorder.rules == {}
